head.script:
scwin.gIsurCd;
scwin.gMktTp;
scwin.gChrgTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.readChargeIssue(grd_List, row, colid);
        scwin.gIsurCd = dts_Grid.getCellData(Number(row), "ISUR_CD");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (grd_adviser.getRowCount() < 1) {
            await $c.win.alert("저장할 정보가 없습니다.");
        } else {
            $c.stf.doLogSave("ULDSTF71001.xml", SCREN_PROCS_TP_CD_07, '');
            $c.data.downloadGridViewExcel(grd_adviser, {fileName: "지정자문인현황", type: "2"});
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71001.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 지정자문인 가져오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {

    // 지정자문인 가져오기
    url += "&SCREN_ID=" + "ULDSTF71001.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/digital/Digitalissueinfo.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Grid.getRowCount() > 0) {
        // 회사정보, 자문현황 가져오기
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } else {
        dts_Corp_Info.removeAll();
    }
};

/**
 * @method
 * @name getChargeIssue
 * @description get Charge Issue 처리
 * @param {String} vISUR_CD vISUR_CD
 * @param {String} vMKT_TP_CD vMKT_TP_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getChargeIssue = async function(vISUR_CD, vMKT_TP_CD) {
    url += "&SCREN_ID=" + "ULDSTF71001.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 회사개요
    const sbmOptions = {
        id : "sbm_dts_Corp_Info",
        action : "/digital/Digitalissueinfo.do",
        ref : "",
        target : "dts_Corp_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 자문종목 현황
    const sbmOptions2 = {
        id : "sbm_dts_Grid_Adviser",
        action : "/digital/Digitalissueinfo.do",
        ref : "",
        target : "dts_Grid_Adviser=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 회사개요>자기자본
    const vStr = txb_Corp_CAP.getValue();
    if (vStr !== "") {
        vStr2 = $c.stf.FormatNumberEx(vStr);
        txb_Corp_CAP.setValue(vStr2);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initSearch
 * @description 다른창에서 담당종목 조회를 클릭할때
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};

/**
 * @method
 * @name readChargeIssue
 * @description read Charge Issue 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readChargeIssue = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    const vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    const vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.gIsurCd = vISUR_CD;
    await scwin.getChargeIssue(vISUR_CD, vMKT_TP_CD);
};

/**
 * @method
 * @name FormatDateEx
 * @description Format Date Ex 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.FormatDateEx = function(str) {
    if (str === "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};
